/* part:page.script.preview.kit.signing-track */
/* The catalog's live preview of kit.signing-track. It rides with the kit and only the catalog page loads it: `adp.py take` leaves it out. */
(function () {
'use strict';
const { html, useState, useEffect, useRef } = window.htmPreact;
const P = window.CatalogPreviews = window.CatalogPreviews || {};
const K = () => window.Kit;
const first = (samples, part) => samples[Object.keys(samples).find(k => k.endsWith('/' + part + '.json'))];
const clone = v => v === undefined ? undefined : JSON.parse(JSON.stringify(v));
const Sim = ({ children }) => html`<p class="pv-sim"><b>Sandbox</b> ${children}</p>`;
const Cases = ({ d, value, set, label = 'Use case' }) => html`<div class="pv-row" role="group" aria-label=${label}><span class="pv-label">${label}</span>
  ${d.cases.map(c => html`<button type="button" key=${c.id} class=${'pv-btn' + (c.id === value ? ' pri' : '')} aria-pressed=${c.id === value} onClick=${() => set(c.id)}>${c.label}</button>`)}</div>`;
const LOG = 'margin:0;font:13px/1.45 var(--f-ui);color:var(--ink-2);min-width:0;flex:1 1 14rem';

P['kit.signing-track'] = ({ samples }) => {
  const d = first(samples, 'signing-track');
  const [id, setId] = useState(d.cases[0].id);
  const c = d.cases.find(x => x.id === id);
  const box = useRef(null), tr = useRef(null);
  const [said, setSaid] = useState('');
  const [signers, setSigners] = useState(() => clone(c.signers));
  // "Next step" stands in for the signer doing it on their phone: the page moves the step and calls update()
  const advance = () => setSigners(ss => { const out = clone(ss); for (const s of out) { const i = s.steps.findIndex(x => x.state !== 'done'); if (i < 0) continue;
    const of = out.find(o => o.key === s.witnesses); if (of && i === s.steps.length - 1 && of.steps[of.steps.length - 1].state !== 'done') continue;
    const x = s.steps[i]; if (x.of && (x.done || 0) < x.of) { x.done = (x.done || 0) + 1; x.state = x.done === x.of ? 'done' : 'now'; } else x.state = 'done';
    if (x.state === 'done' && s.steps[i + 1]) s.steps[i + 1].state = 'now'; return out; } return out; });
  useEffect(() => { const s = clone(c.signers); setSigners(s); setSaid('');
    tr.current = K().signingTrack.mount(box.current, { signers: s, label: c.label, onAction: (sg, a) => setSaid('onAction(' + sg.name + ', "' + a + '"): the page makes the link or QR code') });
    return () => tr.current.destroy(); }, [id]);
  useEffect(() => { if (tr.current) tr.current.update({ signers }); }, [signers]);
  return html`<div class="pv-stack">
    <${Cases} d=${d} value=${id} set=${setId}/>
    <${Sim}>${c.context}<//>
    <div ref=${box}></div>
    <div class="pv-row"><button type="button" class="pv-btn" onClick=${advance}>Next step</button><button type="button" class="pv-btn" onClick=${() => setSigners(clone(c.signers))}>Reset</button>
      <span style=${LOG}>${said || 'Next step plays the first open step, as a signer would; a witness waits for the person they witness.'}</span></div>
  </div>`;
};
})();
/* /part:page.script.preview.kit.signing-track */

