/* part:page.style.kit.signing-track */
/* Kit css: Signing track    kit version 0.1.0    pairs with kit/signing-track.js
   .kit-st > p.kit-st-sum, div.kit-st-meter, ol.kit-st-list > li.kit-st-row(.kit-st-wit) > div.kit-st-who + ol.kit-st-steps (li.kit-st-step[data-state]) + div.kit-st-acts
   step states: done, now, todo, stale (signed on an older text), wait (a witness waiting for the person they witness)
   Below about 34rem (a container query) the rail drops under the name and the buttons under the rail.
   Needs from the board: --panel --sunk --ink --ink-2 --ink-3 --rule --accent --f-ui --f-mono; optional --ok --warn --danger --radius --on-accent */
.kit-st { container-type: inline-size; display: grid; gap: 10px; min-width: 0; font: 15px/1.4 var(--f-ui); color: var(--ink); }
.kit-st-sum { margin: 0; display: flex; flex-wrap: wrap; gap: 4px 12px; align-items: baseline; color: var(--ink-2); }
.kit-st-sum b { color: var(--ink); font-size: 1.15em; }
.kit-st-stale { color: var(--danger, var(--ink)); font-weight: 600; }
.kit-st-meter { height: 6px; border-radius: 3px; background: var(--sunk); overflow: hidden; }
.kit-st-meter span { display: block; height: 100%; background: var(--ok, var(--accent)); transition: width .3s; }
.kit-st-list { margin: 0; padding: 0; list-style: none; display: grid; gap: 6px; }
.kit-st-row { display: grid; grid-template-columns: minmax(8rem, 13rem) minmax(0, 1fr) auto; gap: 8px 16px; align-items: center; padding: 10px 12px; border: 1px solid var(--rule); border-radius: var(--radius, 8px); background: var(--panel); min-width: 0; }
.kit-st-wit { margin-left: 28px; position: relative; background: transparent; border-style: dashed; }
.kit-st-wit::before { content: ""; position: absolute; left: -18px; top: -7px; width: 12px; height: calc(50% + 7px); border-left: 2px solid var(--rule); border-bottom: 2px solid var(--rule); border-bottom-left-radius: 6px; }
.kit-st-who { display: grid; gap: 1px; min-width: 0; } .kit-st-who b { overflow-wrap: anywhere; }
.kit-st-who small { font-size: 13px; color: var(--ink-2); overflow-wrap: anywhere; }
.kit-st-note { font-style: italic; }
.kit-st-steps { margin: 0; padding: 0; list-style: none; display: flex; flex-wrap: wrap; gap: 6px 0; min-width: 0; }
.kit-st-step { position: relative; display: grid; grid-template-columns: auto minmax(0, 1fr); column-gap: 6px; align-items: center; padding-right: 22px; font-size: 13.5px; color: var(--ink-2); min-width: 0; }
.kit-st-step:not(:last-child)::after { content: ""; position: absolute; right: 6px; top: 50%; width: 10px; border-top: 2px solid var(--rule); }
.kit-st-step:not(:last-child)[data-state="done"]::after { border-top-color: var(--ok, var(--ink-2)); }
.kit-st-step i { width: 12px; height: 12px; border-radius: 50%; border: 2px solid var(--ink-3, var(--rule)); background: transparent; }
.kit-st-step small { grid-column: 2; font-size: 12px; }
.kit-st-step[data-state="done"] { color: var(--ink); } .kit-st-step[data-state="done"] i { background: var(--ok, var(--ink-2)); border-color: var(--ok, var(--ink-2)); }
.kit-st-step[data-state="now"] { color: var(--ink); font-weight: 600; } .kit-st-step[data-state="now"] i { border-color: var(--accent); box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 25%, transparent); }
.kit-st-step[data-state="stale"] { color: var(--danger, var(--ink)); } .kit-st-step[data-state="stale"] i { border-color: var(--danger, var(--ink)); background: repeating-linear-gradient(45deg, var(--danger, var(--ink)) 0 2px, transparent 2px 4px); }
.kit-st-step[data-state="wait"] i { border-style: dashed; }
.kit-st-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.kit-st-finished .kit-st-who b::after { content: " ✓"; color: var(--ok, var(--ink-2)); }
.kit-st-acts { display: flex; flex-wrap: wrap; gap: 6px; justify-content: flex-end; }
.kit-st-btn { font: 500 13px/1.2 var(--f-ui); color: var(--ink); background: var(--panel); border: 1px solid var(--rule); border-radius: var(--radius, 6px); padding: 6px 11px; cursor: pointer; white-space: nowrap; }
.kit-st-btn:hover { background: var(--sunk); }
.kit-st-pri { color: var(--on-accent, #fff); background: var(--accent); border-color: var(--accent); } .kit-st-pri:hover { background: var(--accent); filter: brightness(1.08); }
.kit-st-btn:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
@container (max-width: 44rem) { .kit-st-row { grid-template-columns: minmax(0, 1fr) auto; } .kit-st-steps { grid-column: 1 / -1; grid-row: 2; } }
@container (max-width: 30rem) { .kit-st-row { grid-template-columns: minmax(0, 1fr); } .kit-st-acts { justify-content: flex-start; } .kit-st-wit { margin-left: 18px; } .kit-st-wit::before { left: -12px; width: 8px; } }
@media (prefers-reduced-motion: reduce) { .kit-st-meter span { transition: none; } }
/* /part:page.style.kit.signing-track */

/* part:page.script.kit.signing-track */
/**
 * Signing track
 * Kit.signingTrack.mount(box, {signers}) shows everyone who signs or witnesses a document, in signing order, each with a rail of their steps and how far they are. A witness sits under the person they witness, and their signing step waits until that person has signed. A step made on an older text shows as stale ("text changed, sign again"). The steps are data, so a case without ID photos or initials simply has fewer.
 *
 * What it is: the progress board of a signing round (an offer letter, a board resolution, a tenancy with witnesses, a consent form). It shows; it decides nothing.
 * The page owns the links: the kit reports onAction(signer, action) for buttons like "Copy link" or "Show QR code", and the page makes and shows them.
 * API (small and stable):
 *   Kit.signingTrack.mount(box, {signers, actions, label, words, onAction}) -> {update(opts), destroy()}
 *     signers  [{key, name, label, witnesses, note, steps: [{id, label, state, done, of}]}]
 *              witnesses  the key of the signer this one witnesses ("" for a party); the row moves under that signer
 *              state      "done" | "now" | "todo" | "stale"; done/of show a count (initials on 2 of 4 pages)
 *              the last step is the signature: a signer has signed when it is done
 *     actions  [{id, label, when}] buttons per signer (default Copy link, Show QR code); when "open" (default) shows them only
 *              to a signer who has not finished, "always" to everyone
 *     words    {stale, waits, signed, of}   replace the kit's words ("text changed, sign again", "after", "have signed", "of")
 *     onAction(signer, actionId)
 *
 * @id        kit.signing-track
 * @kind      component
 * @group     Kit
 * @status    new
 * @version   0.1.0
 * @updated   2026-11-21
 * @summary   Everyone who signs or witnesses, in signing order, with a rail of their steps; witnesses wait for the person they witness, and a signature on an older text shows as stale.
 * @tags      signing, signature, witness, progress, steps, signers, contract, consent, board resolution, offer letter, e-sign, roster
 * @requires  none
 * @files     kit/signing-track.css, kit/samples/signing-track.json, kit/previews/signing-track.js
 * @provides  Kit.signingTrack.mount
 * @config    Kit.signingTrack.mount(box, opts) | signers [{key, name, label, witnesses, note, steps: [{id, label, state, done, of}]}], actions [{id, label, when}], label, words; returns {update(opts), destroy()}
 * @config    events | onAction(signer, actionId); the kit makes no links itself
 * @tokens    --panel --sunk --ink --ink-2 --ink-3 --rule --accent --ok? --warn? --danger? --f-ui --f-mono --radius? --on-accent?
 * @globals   none
 * @db        none
 * @source    Catalog harvest, 2026-11-21 | an agreement review board | the signers, witnesses and their steps
 * @preview   {"render": "kit.signing-track", "samples": ["kit/samples/signing-track.json"]}
 */
(function () {
'use strict';
const Kit = window.Kit = window.Kit || { version: '0.1.0' };
const el = (tag, cls, txt) => { const e = document.createElement(tag); if (cls) e.className = cls; if (txt != null) e.textContent = txt; return e; };
const WORDS = { stale: 'text changed, sign again', waits: 'after', signed: 'have signed', of: 'of' };
const ACTIONS = [{ id: 'link', label: 'Copy link' }, { id: 'qr', label: 'Show QR code' }];
const last = s => (s.steps || [])[(s.steps || []).length - 1];
const signed = s => { const l = last(s); return !!l && l.state === 'done'; };

// parties in the order given, each followed by the people who witness them
function ordered(signers) {
  const keys = new Set(signers.map(s => s.key)), out = [];
  const add = s => { out.push(s); signers.filter(w => w.witnesses && w.witnesses === s.key).forEach(add); };
  signers.filter(s => !s.witnesses || !keys.has(s.witnesses)).forEach(add);
  return out;
}

function mount(box, opts) {
  const o = Object.assign({ signers: [], actions: ACTIONS, label: 'Signers', words: {}, onAction: null }, opts);
  box.classList.add('kit-st');
  function row(s, byKey) {
    const w = Object.assign({}, WORDS, o.words), of = byKey[s.witnesses];
    const li = el('li', 'kit-st-row' + (of ? ' kit-st-wit' : '')); li.dataset.key = s.key || '';
    const steps = (s.steps || []).map(x => Object.assign({}, x));
    const sig = steps[steps.length - 1];
    if (of && sig && sig.state !== 'done' && !signed(of)) { sig.state = 'wait'; sig.waits = of.name; }
    const open = steps.find(x => x.state !== 'done');
    if (!open) li.classList.add('kit-st-finished');
    const who = el('div', 'kit-st-who'); who.append(el('b', null, s.name || ''), el('small', null, s.label || ''));
    if (s.note) who.append(el('small', 'kit-st-note', s.note));
    const ol = el('ol', 'kit-st-steps'); ol.setAttribute('aria-label', 'Steps for ' + (s.name || ''));
    steps.forEach(x => {
      const st = el('li', 'kit-st-step'); st.dataset.state = x.state || 'todo';
      if (x.state === 'now') st.setAttribute('aria-current', 'step');
      const dot = el('i'); dot.setAttribute('aria-hidden', 'true');
      let t = x.label || ''; if (x.of) t += ' ' + (x.done || 0) + '/' + x.of;
      const state = { done: 'done', now: 'in progress', todo: 'to do', stale: w.stale, wait: w.waits + ' ' + (x.waits || '') }[x.state || 'todo'];
      const sr = el('span', 'kit-st-sr', ', ' + state);
      st.append(dot, el('span', 'kit-st-sl', t));
      if (x.state === 'stale' || x.state === 'wait') st.append(el('small', null, x.state === 'stale' ? w.stale : w.waits + ' ' + x.waits)); else st.append(sr);
      ol.append(st);
    });
    li.append(who, ol);
    if (o.onAction && o.actions.length) {
      const acts = el('div', 'kit-st-acts'), shown = o.actions.filter(a => (a.when || 'open') === 'always' || open);
      shown.forEach((a, i) => {
        const b = el('button', 'kit-st-btn' + (i === 0 && open && (open.state === 'now' || open.state === 'stale') ? ' kit-st-pri' : ''), a.label); b.type = 'button';
        b.setAttribute('aria-label', a.label + ': ' + (s.name || '')); b.onclick = () => o.onAction(s, a.id); acts.append(b);
      });
      if (shown.length) li.append(acts);
    }
    return li;
  }
  function draw() {
    box.textContent = '';
    const w = Object.assign({}, WORDS, o.words), byKey = {};
    o.signers.forEach(s => { if (s.key) byKey[s.key] = s; });
    const n = o.signers.filter(signed).length, stale = o.signers.filter(s => (s.steps || []).some(x => x.state === 'stale')).length;
    const sum = el('p', 'kit-st-sum'); sum.setAttribute('aria-live', 'polite');
    sum.append(el('b', null, n + ' ' + w.of + ' ' + o.signers.length), document.createTextNode(' ' + w.signed));
    if (stale) sum.append(el('span', 'kit-st-stale', stale + ' to redo: ' + w.stale));
    const bar = el('div', 'kit-st-meter'); bar.setAttribute('aria-hidden', 'true'); const fill = el('span'); fill.style.width = (o.signers.length ? n / o.signers.length * 100 : 0) + '%'; bar.append(fill);
    const ul = el('ol', 'kit-st-list'); ul.setAttribute('aria-label', o.label);
    ordered(o.signers).forEach(s => ul.append(row(s, byKey)));
    box.append(sum, bar, ul);
  }
  draw();
  return { update(next) { Object.assign(o, next || {}); draw(); }, destroy() { box.textContent = ''; box.classList.remove('kit-st'); } };
}
Kit.signingTrack = Object.freeze({ mount });
})();
/* /part:page.script.kit.signing-track */
